# generate transforms normalized for marker mask 3x5
base=set(mask)
def transforms(S):
 out=[]
 for refl in (False,True):
  for k in range(4):
   pts=[]
   for r,c in S:
    if refl:c=-c
    for _ in range(k):r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts);mc=min(c for r,c in pts)
   t=frozenset((r-mr,c-mc) for r,c in pts)
   if t not in out:out.append(t)
 return out
forms=transforms(base); marked=set()
for S in forms:
 h=max(r for r,c in S)+1;w=max(c for r,c in S)+1
 for i in range(len(a)-h+1):
  for j in range(len(a[0])-w+1):
   if all(a[i+r][j+c]==0 for r,c in S): marked.update((i+r,j+c) for r,c in S)
out3=[[9 if (i,j) in marked else v for j,v in enumerate(row)] for i,row in enumerate(a)]
print(out3)

# template match test marker 9 zeros, nonmarker background 8, all transforms
patterns=transforms(base); mark_bg=set()
for S in patterns:
 h=max(r for r,c in S)+1;w=max(c for r,c in S)+1
 for i in range(len(a)-h+1):
  for j in range(len(a[0])-w+1):
   if all((a[i+r][j+c]==0 if (r,c) in S else a[i+r][j+c]==8) for r in range(h) for c in range(w)):
